//! Native App reporting from a synchronous requestSubmit invocation.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn form_request_actual_app_required_report_editing_canceled_submit_and_paint(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-form-request-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form id=owner><input id=field name=q required><button id=chosen name=choice>Send</button></form><button id=go name=go type=button>Request</button><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var form=document.getElementById('owner'),invalid=0,submitted=0;form.addEventListener('invalid',function(e){if(!e.isTrusted)throw 'invalid metadata';invalid++;},true);form.onsubmit=function(e){if(!e.isTrusted||!(e instanceof SubmitEvent)||e.submitter!==document.getElementById('chosen'))throw 'submit metadata';submitted++;e.preventDefault();document.getElementById('paint').className='done';};document.getElementById('go').onclick=function(){form.requestSubmit(document.getElementById('chosen'));if(invalid===1&&submitted===0)document.title='Invalid';else if(invalid===1&&submitted===1)document.title='Submitted';else throw 'synchronous ordering';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let field=node(&app,"field");let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let before=app.draw();click(&mut app,go);assert_eq!(app.document.title,"Invalid");assert!(app.failed);assert_eq!(app.status,"Complete the required field: q.");assert!(matches!(app.focus,Focus::Control(n)if n==field));for ch in ['A','😀','Z']{app.text_input(ch);}click(&mut app,go);assert_eq!(app.document.title,"Submitted");assert!(!app.failed&&!app.is_loading());assert!(app.status.is_empty());assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==field).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));let chosen=node(&app,"chosen");let outcome=app.scripting.as_mut().unwrap().console_eval(&mut app.document,&mut app.forms,"var nativeInvalid=0,nativeSubmit=0;document.getElementById('field').value='';document.getElementById('field').oninvalid=function(e){nativeInvalid++;form.requestSubmit(document.getElementById('chosen'));if(nativeInvalid!==1)throw 'native invalid recursion';e.preventDefault();document.title='Native invalid guard';};form.onsubmit=function(e){nativeSubmit++;form.requestSubmit(document.getElementById('chosen'));if(nativeSubmit!==1)throw 'native submit recursion';e.preventDefault();document.title='Native submit guard';};");assert_eq!(outcome.errors,0,"{}",app.scripting.as_ref().unwrap().report());click(&mut app,chosen);assert_eq!(app.document.title,"Native invalid guard");click(&mut app,field);app.text_input('X');click(&mut app,chosen);assert_eq!(app.document.title,"Native submit guard");assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let outcome=app.scripting.as_mut().unwrap().console_eval(&mut app.document,&mut app.forms,"form.onsubmit=function(e){e.preventDefault();document.title='Native guard restored';};form.requestSubmit(document.getElementById('chosen'));");assert_eq!(outcome.errors,0);assert_eq!(app.document.title,"Native guard restored");
}
